let items=[artifact],snapshot={revision:1,projects:[],connections:[{id:'conn',provider:'ollama',name:'Fixture',baseUrl:'http://localhost:11434',enabledModels:['fixture'],favoriteModels:[],modelLabels:{}}],defaultModel:{connectionId:'conn',model:'fixture'},conversations:[{id:'chat',title:'Plan chat',connectionId:'conn',model:'fixture',messages:[]},{id:'other',title:'Other chat',connectionId:'conn',model:'fixture',messages:[]}],chatView:{selected:'chat',projectId:null,projectHome:false,positions:{}},drafts:{}};
let notifyChat,notifyArtifacts;window.events=[];
const host={workspace:{layout:{view:'Chat'},notes:[],tasks:[],settings:{},profile:{}},closing:false,registerFlush:()=>()=>{},commands:{register:()=>()=>{},run:()=>true},navigate:()=>{},notify:m=>window.events.push(['notify',m]),services:{chat:{load:()=>ok(snapshot),subscribe:fn=>{notifyChat=fn;return()=>{}},createConversation:()=>new Promise(resolve=>{window.finishNewChat=()=>{const c={...snapshot.conversations[1],id:'new-chat'};snapshot={...snapshot,conversations:[...snapshot.conversations,c],revision:snapshot.revision+1};notifyChat(snapshot);resolve({ok:true,value:c})}}),saveDraft:()=>ok(null),saveChatView:()=>ok(null),toolOptions:()=>ok([]),models:()=>ok([{name:'fixture',size:0}]),inspectContext:()=>ok({referenceBytes:0,conversationBytes:0,error:''}),send:input=>{window.events.push(['send',input]);const m={id:'reply2',role:'assistant',content:'Updated your document.',thinking:'',status:'streaming',createdAt:2,error:'',context:[]};snapshot={...snapshot,revision:snapshot.revision+1,conversations:snapshot.conversations.map(c=>c.id===input.conversationId?{...c,messages:[...c.messages,m]}:c)};notifyChat(snapshot);window.finishRevision=()=>{const version={...first,id:'v2',number:2,source:{...source,generatedFileId:'file2'}};items=[{...artifact,versions:[first,version]}];notifyArtifacts(items);snapshot={...snapshot,revision:snapshot.revision+1,conversations:snapshot.conversations.map(c=>({...c,messages:c.messages.map(m=>m.id==='reply2'?{...m,status:'complete',generatedFiles:[{id:'file2',name:'Plan.docx',mime:first.mime,size:20}]}:m)}))};notifyChat(snapshot)};return ok(snapshot)}},artifacts:{list:()=>ok(items),subscribe:fn=>{notifyArtifacts=fn;return()=>{}},version:target=>ok({...items[0].versions.find(v=>v.id===target.versionId),content:'# Plan\nOriginal content',format:'docx'}),document:target=>ok({...window.documentFiles[target.versionId],format:'docx'}),status:()=>ok({warning:''}),importGenerated:()=>ok(items[0])},voice:{status:()=>ok({}),settings:()=>ok({})},clipboard:{writeText:()=>ok(null)}}};
